    let mut acc = 0u64;
    for line in lines {
        for t in oracle::tokenize(line) {
            match t {
                Ok(oracle::Token::Timestamp(s)) | Ok(oracle::Token::Key(s)) => acc += s.len() as u64,
                Ok(_) => acc += 1,
                Err(_) => break,
            }
        }
    }
    acc
}

