// Differential check and benchmark: new `logscan` tokenizer vs frozen original (`oracle`).
// Run with `cargo run --release -- check` or `cargo run --release -- bench`.
use std::hint::black_box;
use std::time::Instant;

fn new_tokens(line: &str) -> String {
    format!("{:?}", logscan::tokenize(line).collect::<Vec<_>>())
}

fn old_tokens(line: &str) -> String {
    format!("{:?}", oracle::tokenize(line).collect::<Vec<_>>())
}

fn check_one(line: &str, mismatches: &mut u64, checked: &mut u64) {
    *checked += 1;
    let (a, b) = (old_tokens(line), new_tokens(line));
    if a != b {
        *mismatches += 1;
        if *mismatches <= 10 {
            eprintln!("MISMATCH on {line:?}\n  old: {a}\n  new: {b}");
        }
    }
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

fn check() {
    // Every ASCII-structural alphabet string up to length 7, plus multibyte characters.
    let alphabet: Vec<char> = "[]\"\\= \ta\nn".chars().collect();
    let mut mismatches = 0u64;
    let mut checked = 0u64;
    for len in 0..=7u32 {
        let total = (alphabet.len() as u64).pow(len);
        for mut code in 0..total {
            let mut s = String::new();
            for _ in 0..len {
                s.push(alphabet[(code % alphabet.len() as u64) as usize]);
                code /= alphabet.len() as u64;
            }
            check_one(&s, &mut mismatches, &mut checked);
        }
    }
    let extra: Vec<char> = "é[]\"=\\ \tü".chars().collect();
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..3_000_000 {
        let len = (rng.next() % 60) as usize;
        let pool: &[char] = if rng.next() % 4 == 0 { &extra } else { &alphabet };
        let s: String = (0..len).map(|_| pool[(rng.next() % pool.len() as u64) as usize]).collect();
        check_one(&s, &mut mismatches, &mut checked);
    }
    println!("checked {checked} lines, mismatches {mismatches}");
    if mismatches > 0 {
        std::process::exit(1);
    }
}

fn corpus() -> String {
    let mut rng = Rng(42);
    let mut out = String::new();
    for _ in 0..1_000_000 {
        match rng.next() % 10 {
            0 => out.push_str("[2024-05-01T12:00:00Z] level=warn msg=\"disk 91% full\" retries= done\n"),
            1 => out.push_str("started worker-3 ok\n"),
            2 => out.push_str("a=\"open\n"),
            _ => out.push_str("[2024-05-01T12:00:01Z] level=info msg=\"say \\\"hi\\\"\\n\" user=ann host=db-7 ms=12\n"),
        }
    }
    out
}

fn count_new(lines: &[&str]) -> u64 {
    let mut acc = 0u64;
    for line in lines {
        for t in logscan::tokenize(line) {
            match t {
                Ok(logscan::Token::Timestamp(s)) | Ok(logscan::Token::Key(s)) => acc += s.len() as u64,
                Ok(_) => acc += 1,
                Err(_) => break,
            }
        }
    }
    acc
}

fn count_old(lines: &[&str]) -> u64 {
    let mut acc = 0u64;
    for line in lines {
        for t in oracle::tokenize(line) {
            match t {
                Ok(oracle::Token::Timestamp(s)) | Ok(oracle::Token::Key(s)) => acc += s.len() as u64,
                Ok(_) => acc += 1,
                Err(_) => break,
            }
        }
    }
    acc
}

fn time(f: fn(&[&str]) -> u64, lines: &[&str]) -> f64 {
    let start = Instant::now();
    black_box(f(black_box(lines)));
    start.elapsed().as_secs_f64()
}

fn bench() {
    let buf = corpus();
    let lines: Vec<&str> = buf.lines().collect();
    let (mut old_t, mut new_t) = (Vec::new(), Vec::new());
    for _ in 0..3 {
        time(count_old, &lines);
        time(count_new, &lines);
    }
    for _ in 0..15 {
        old_t.push(time(count_old, &lines));
        new_t.push(time(count_new, &lines));
    }
    old_t.sort_by(|a, b| a.partial_cmp(b).unwrap());
    new_t.sort_by(|a, b| a.partial_cmp(b).unwrap());
    println!("lines: {}", lines.len());
    println!("old: min {:.4}s median {:.4}s", old_t[0], old_t[old_t.len() / 2]);
    println!("new: min {:.4}s median {:.4}s", new_t[0], new_t[new_t.len() / 2]);
    println!("new/old median ratio: {:.3}", new_t[new_t.len() / 2] / old_t[old_t.len() / 2]);
}

fn main() {
    match std::env::args().nth(1).as_deref() {
        Some("check") => check(),
        Some("bench") => bench(),
        _ => {
            eprintln!("usage: logscan-diff check|bench");
            std::process::exit(2);
        }
    }
}

